corrected_code:
const crypto = require('crypto');

router.post('/webhooks/github', express.json(), async (req, res) => {
  const signature = req.headers['x-hub-signature-256'];
  const hmac = crypto.createHmac('sha256', process.env.GITHUB_WEBHOOK_SECRET);
  const digest = 'sha256=' + hmac.update(JSON.stringify(req.body)).digest('hex');

  if (!signature || !crypto.timingSafeEqual(Buffer.from(signature), Buffer.from(digest))) {
    return res.status(401).send('Invalid signature');
  }

  const { action, pull_request, repository, installation } = req.body;
  if (action === 'closed' && pull_request?.merged) {
    const pipeline = await DeploymentPipeline.findOne({
      githubRepoId: repository.id,
      githubInstallationId: installation?.id,
      isActive: true
    });
    if (!pipeline) {
      return res.status(403).send('Repository not bound to active tenant deployment pipeline');
    }
    await buildServer.triggerDeployment(pipeline.productionEnvironmentId, pull_request.head.sha);
  }
  res.status(200).send('Webhook processed');
});
